        // restart host (experimental)
        ["Restart host"] = "Spel herstarten",
        ["Experimental"] = "Experimenteel",
        ["After a save made low on memory, offers to start the game again into that save when you quit."] = "Na het opslaan met weinig geheugen biedt het bij afsluiten aan het spel opnieuw te starten in die opslag.",
        ["Start the game once with Apex Radiance, then turn on the restart host here."] = "Start het spel één keer met Apex Radiance en zet daarna hier het herstarten van het spel aan.",
        ["Removes ts3wrap.exe and turns the restart host off in ApexRadiance.toml."] = "Verwijdert ts3wrap.exe en zet het herstarten van het spel uit in ApexRadiance.toml.",
        ["Your NVIDIA card draws an extra picture between every two the game makes, so the game looks about twice as smooth. Only on RTX 40 and 50 series cards; best with the frame limit at 60 to 90 fps."] = "Je NVIDIA-kaart tekent een extra beeld tussen elke twee beelden van het spel, zodat het spel er ongeveer twee keer zo vloeiend uitziet. Alleen op RTX 40- en 50-serie kaarten; het best met een framelimiet van 60 tot 90 fps.",
        ["On for The Sims 3 in the NVIDIA driver. Works best with Apex's frame limit at 60 to 90 fps."] = "Aan voor De Sims 3 in de NVIDIA-driver. Werkt het best met de framelimiet van Apex op 60 tot 90 fps.",
        ["On for The Sims 3 in the NVIDIA driver. Apex's frame limit is now 60 fps, the pace it works best at."] = "Aan voor De Sims 3 in het NVIDIA-stuurprogramma. De framelimiet van Apex is nu 60 fps, het tempo waarmee het het best werkt.",
        ["Off for The Sims 3."] = "Uit voor De Sims 3.",
        ["Already in your NVIDIA profile \"{0}\": Setup leaves it as it is."] = "Staat al in je NVIDIA-profiel \"{0}\": Setup laat het zoals het is.",
        ["Needs an NVIDIA GeForce RTX 40 or 50 series card (found: {0})."] = "Vereist een NVIDIA GeForce RTX 40- of 50-serie kaart (gevonden: {0}).",
        ["Needs NVIDIA driver 571.86 or newer (found: {0})."] = "Vereist NVIDIA-driver 571.86 of nieuwer (gevonden: {0}).",
        ["Needs the RTX Remix bridge as the graphics choice."] = "Vereist de RTX Remix bridge als grafische keuze.",
        ["Could not read the NVIDIA driver settings: {0}"] = "Kan de instellingen van de NVIDIA-driver niet lezen: {0}",
        ["Could not change the NVIDIA driver settings: {0}"] = "Kan de instellingen van de NVIDIA-driver niet wijzigen: {0}",
        ["Turn on {0}"] = "{0} aanzetten",
        ["Turn off {0}"] = "{0} uitzetten",
        ["The AMD driver adds frames for smoother motion, about double the frame rate, with a little more input delay. It applies to every game on this PC."] = "De AMD-driver voegt frames toe voor vloeiendere beweging, ongeveer dubbele framerate, met iets meer invoervertraging. Geldt voor alle games op deze pc.",
        ["Not available on this AMD card or driver: AMD Fluid Motion Frames needs a Radeon RX 6000 series card or newer and a recent driver."] = "Niet beschikbaar op deze AMD-kaart of driver: AMD Fluid Motion Frames vereist een Radeon RX 6000-serie of nieuwer en een recente driver.",
        ["Could not read the AMD driver settings: {0}"] = "Kan de instellingen van de AMD-driver niet lezen: {0}",
        ["Could not change the AMD driver settings: {0}"] = "Kan de instellingen van de AMD-driver niet wijzigen: {0}",
        ["On in the AMD driver, for every game. Apex's frame limit is now 60 fps, the pace it works best at."] = "Aan in de AMD-driver, voor alle games. De framelimiet van Apex is nu 60 fps, het tempo waarop het het best werkt.",
        ["On in the AMD driver, for every game. Works best with Apex's frame limit at 60 to 90 fps."] = "Aan in de AMD-driver, voor alle games. Werkt het best met de framelimiet van Apex op 60 tot 90 fps.",
        ["Off in the AMD driver."] = "Uit in de AMD-driver.",
        ["Apex frame limit"] = "Framelimiet van Apex",
        ["{0} doubles what you see: a 60 fps limit shows about 120 on screen. Works best at 60 to 90 fps."] = "{0} verdubbelt wat je ziet: een limiet van 60 fps toont er ongeveer 120 op het scherm. Werkt het best op 60 tot 90 fps.",
        ["Off"] = "Uit",
